INSERT INTO assessment_categories (name, code, order_index, description) VALUES
  ('Business Continuity, Disaster recovery, Backup', 'bcp', 0, 'Piani e procedure per garantire la continuità operativa e il ripristino in caso di disastro.'),
  ('Certificazioni', 'cert', 1, 'Adozione e mantenimento di certificazioni di sicurezza (ISO 27001).'),
  ('Crittografia', 'crypto', 2, 'Utilizzo e gestione della crittografia per la protezione dei dati.'),
  ('Gestione delle identità Gestione degli accessi', 'iam', 3, 'Controllo degli accessi, autenticazione e gestione delle identità digitali.'),
  ('Gestione degli incidenti', 'incident', 4, 'Preparazione, rilevamento e gestione degli incidenti di sicurezza informatica.'),
  ('Gestione del rischio', 'risk', 5, 'Processi strutturati di valutazione e gestione dei rischi cyber secondo le normative NIS2.'),
  ('Gestione delle risorse', 'asset', 6, 'Identificazione, classificazione e gestione delle risorse e degli asset IT.'),
  ('Gestione fornitori e acquisti', 'supply', 7, 'Valutazione e gestione dei rischi legati ai fornitori e alla catena di approvvigionamento.'),
  ('Governance', 'gov', 8, 'Struttura di gestione della sicurezza, definizione delle responsabilità, strategie e politiche di cybersecurity.'),
  ('HR e formazione', 'hr', 9, 'Formazione del personale, consapevolezza e gestione delle competenze in ambito cybersecurity.'),
  ('Igiene informatica', 'hygiene', 10, 'Pratiche fondamentali di igiene informatica per la protezione quotidiana.'),
  ('Manutenzione e miglioramento continuo', 'maint', 11, 'Processi di reporting, comunicazione delle violazioni e conformità agli obblighi normativi.'),
  ('Network Security Best Practices & Operations', 'netsec', 12, 'Adozione delle migliori pratiche per la gestione operativa della sicurezza IT.'),
  ('Sviluppo software', 'swdev', 13, 'Sicurezza nel ciclo di sviluppo del software e gestione delle vulnerabilità.')
INSERT INTO assessment_questions (category_id, order_index, question_text, description) VALUES
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 1, 'L''organizzazione ha definito e documentato gli obiettivi di continuità operativa che devono essere perseguiti nella gestione degli scenari di crisi?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 2, 'L''organizzazione ha effettuato una business impact analysis per identificare i servizi essenziali e individuare le risorse necessarie per garantirne l''erogazione?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 3, 'Esistono criteri per valutare la gravità dell''interruzione operativa causata da un incidente?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 4, 'La sicurezza delle informazioni e la continuità dei servizi essenziali sono stati descritti/documentati e inclusi nei piani di continuità (BCP)?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 5, 'L''organizzazione ha approvato politiche e procedure per la gestione del backup di dati e applicazioni su dispositivi, supporti di archiviazione, cloud, DB e server?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 6, 'L''organizzazione ha predisposto soluzioni di disaster recovery (DR)?', 'Priorità: BASSA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 7, 'L''Organizzazione ha prevista la ridondanza di tutti i sistemi per garantire la disponibilità dell''impianto di elaborazione delle informazioni ed erogazione dei servizi principali?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 8, 'La tua organizzazione gestisce e verifica le procedure di backup delle informazioni?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 9, 'Eseguite test sui vostri sistemi di backup per garantire che i dati possano essere ripristinati correttamente?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 10, 'Il personale coinvolto riceve formazione e partecipa a esercitazioni di simulazione di crisi?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'bcp'), 11, 'Esiste un processo per gestire i requisiti di capacity di tutti i sistemi in base al processo aziendale e alla sua criticità?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'cert'), 12, 'L''Organizzazione ha implementato un sistema per la gestione della qualità certificato ISO 9001?', 'Priorità: BASSA'),
  ((SELECT id FROM assessment_categories WHERE code = 'cert'), 13, 'L''Organizzazione ha implementato un sistema per la gestione della qualità certificato ISO/IEC 27001?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'cert'), 14, 'Esiste una procedura per monitorare la disponibilità di nuovi schemi di certificazione, linee guida e indicazioni per la sicurezza sicurezza?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'crypto'), 15, 'La tua organizzazione utilizza soluzioni di comunicazione vocale, video e di testo protette?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'crypto'), 16, 'Esistono politiche per l''utilizzo di strumenti di videoconferenza protetti per garantire la sicurezza delle riunioni aziendali?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'crypto'), 17, 'I dispositivi aziendali sono crittografati e protetti contro gli accessi non autorizzati?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'crypto'), 18, 'La crittografia è applicata a tutte le comunicazioni di rete per evitare intercettazioni?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'crypto'), 19, 'Le chiavi crittografiche sono protette contro l''accesso non autorizzato e lo smarrimento?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'crypto'), 20, 'Disponete di politiche e procedure formali e documentate che specificano l''uso della crittografia e della cifratura all''interno della vostra organizzazione?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 21, 'La tua organizzazione gestisce le autorizzazioni all''accesso a reti e sistemi (inclusi i privilegi minimi e la separazione dei compiti)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 22, 'Esiste una politica/procedura documentata che descrive il processo di gestione degli accessi logici e fisici a reti e sistemi?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 23, 'Applicate il principio del privilegio minimo, assicurandovi che gli utenti abbiano solo l''accesso necessario per svolgere le loro funzioni lavorative?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 24, 'Esistono procedure per concedere e revocare l''accesso in base a cambiamenti di ruolo, promozioni o interruzioni del rapporto di collaborazione?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 25, 'I profili autorizzativi e i diritti di accesso sono rivisti periodicamente?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 26, 'Gli utenti di reti e sistemi dispongono di identificativo (user ID) univoco?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 27, 'Avete adottato una politica per l''utilizzo di password di accesso sicure?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 28, 'Monitorate e registrate l''accesso logico ai sistemi e ai dati critici?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 29, 'I log di accesso vengono verificati periodicamente per individuare attività insolite o non autorizzate?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 30, 'Esistono strumenti per verificare e modificare regolarmente i diritti di accesso?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 31, 'La tua organizzazione gestisce l''accesso remoto?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 32, 'Utilizzate metodi di autenticazione avanzati (ad esempio autenticazione a più fattori, MFA) per accedere a sistemi critici e informazioni sensibili, ivi inclusi i dati particolari?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 33, 'La tua organizzazione gestisce e protegge l''accesso fisico alle risorse?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 34, 'Esistono politiche e procedure per gestire l''accesso fisico, inclusi meccanismi di controllo degli ingressi e strumenti come i badge?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 35, 'La tua organizzazione gestisce le identità e le credenziali per le entità autorizzate, le funzioni e le transazioni?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'iam'), 36, 'Ogni utente è dotato di un identificativo unico e personale (User ID) per garantire la tracciabilità delle azioni svolte?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 37, 'L''organizzazione ha istituito un team dedicato alla gestione degli incidenti di sicurezza informatica (IRT o CSIRT)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 38, 'Sono state definite e documentate le politiche e le procedure per la gestione degli incidenti di sicurezza, incluse le fasi di individuazione, analisi e classificazione, contenimento, eradicazione, ripristino e attività post-incidente?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 39, 'Esistono meccanismi per la notifica tempestiva di un incidente ai soggetti interni ed esterni pertinenti (ad esempio, autorità, clienti, partner)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 40, 'Sono stati stabiliti livelli di classificazione per valutare la gravità degli incidenti e determinare le azioni di risposta appropriate?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 41, 'Esiste un processo di lessons learned per analizzare gli incidenti passati e migliorare le misure di prevenzione e risposta?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 42, 'Il personale è formato sulle procedure di gestione degli incidenti e partecipa regolarmente a esercitazioni e simulazioni?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 43, 'L''organizzazione dispone di un piano di comunicazione interna ed esterna in caso di incidente significativo?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 44, 'Viene effettuato il monitoraggio continuo degli eventi di sicurezza e delle anomalie di rete?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 45, 'Sono implementate soluzioni tecnologiche per il rilevamento automatizzato degli incidenti (IDS, IPS, SIEM, EDR)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 46, 'L''organizzazione è in grado di isolare rapidamente i sistemi compromessi per contenere un incidente?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 47, 'È stato definito e pianificato un iter autorizzativo per determinare la notifica di un incidente significativo allo CSIRT Italia e/o all''Autorità competente NIS, in conformità con la Direttiva NIS2?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 48, 'Esistono procedure per la raccolta e la conservazione delle prove digitali in caso di indagini forensi?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 49, 'L''organizzazione partecipa a network di condivisione delle informazioni sulle minacce (ISAC, CERT nazionali o europei)?', 'Priorità: BASSA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 50, 'I rapporti sugli incidenti vengono condivisi internamente per aumentare la consapevolezza del personale?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 51, 'L''organizzazione implementa un processo di rilevamento e gestione delle violazioni dei dati personali (data breach) in conformità con il GDPR e la NIS2?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 52, 'Sono state implementate procedure per rispondere a diversi tipi di incidenti (ransomware, phishing, DDoS, insider threat, ecc.)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 53, 'Esistono accordi di supporto con fornitori esterni specializzati per la gestione di incidenti complessi?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 54, 'L''organizzazione dispone di strumenti e procedure per il ripristino rapido dei servizi essenziali dopo un incidente?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 55, 'Sono stati implementati canali sicuri di comunicazione per scambiare informazioni tra i responsabili della sicurezza riguardo la gestione dell''incidente?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 56, 'Il piano di gestione degli incidenti viene rivisto e aggiornato almeno annualmente o dopo ogni incidente significativo?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 57, 'Sono state stabilite metriche e indicatori chiave (KPI) per misurare l''efficacia del processo di gestione degli incidenti (tempo medio di rilevamento, tempo medio di risposta, ecc.)?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 58, 'Esiste un processo di escalation chiaro per gestire gli incidenti che richiedono il coinvolgimento di livelli decisionali superiori?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 59, 'L''organizzazione ha previsto la gestione degli incidenti di sicurezza anche dal punto di vista legale e contrattuale (ad esempio, notifiche ai clienti, obblighi verso i partner)?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'incident'), 60, 'L''organizzazione dispone di una copertura assicurativa contro i rischi derivanti da incidenti informatici (cyber insurance)?', 'Priorità: BASSA'),
  ((SELECT id FROM assessment_categories WHERE code = 'risk'), 61, 'L''organizzazione ha definito e implementato un processo di analisi del rischio che considera le principali minacce cyber e le vulnerabilità dei propri sistemi?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'risk'), 62, 'L''analisi del rischio copre anche i rischi legati ai fornitori e alla catena di approvvigionamento?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'risk'), 63, 'Vengono valutati regolarmente (almeno annualmente) i rischi derivanti dall''uso di nuove tecnologie e dall''evoluzione delle minacce informatiche?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'risk'), 64, 'Esiste un registro dei rischi (risk register) che documenta i rischi identificati, le relative valutazioni e le misure di mitigazione adottate?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'risk'), 65, 'L''organizzazione ha definito criteri di accettazione del rischio (risk appetite) approvati dal management?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'risk'), 66, 'Vengono condotte analisi di rischio specifiche prima dell''introduzione di nuovi sistemi, servizi o modifiche significative all''infrastruttura IT?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'risk'), 67, 'Le misure di mitigazione dei rischi identificati sono monitorate e la loro efficacia viene rivalutata periodicamente?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'risk'), 68, 'L''analisi del rischio include la valutazione dell''impatto operativo, finanziario e reputazionale di un potenziale incidente di sicurezza?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 69, 'L''organizzazione mantiene un inventario completo e aggiornato di tutti gli asset IT (hardware, software, dati, infrastrutture di rete)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 70, 'Gli asset IT sono classificati in base alla loro criticità per il business e alla sensibilità dei dati che trattano?', 'Priorità: ALTA'),
