  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 73, 'Le politiche di gestione degli asset IT prevedono la rimozione sicura dei dati prima della dismissione o del riutilizzo dei dispositivi?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 74, 'Esiste un processo di monitoraggio per rilevare asset non autorizzati o non gestiti all''interno della rete aziendale?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 75, 'L''inventario degli asset viene aggiornato automaticamente o comunque con cadenza regolare?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 76, 'Le responsabilità per la gestione e la sicurezza di ciascun asset sono chiaramente assegnate a un proprietario (asset owner)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 77, 'L''organizzazione utilizza strumenti di discovery automatizzati per identificare nuovi dispositivi e servizi connessi alla rete?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 78, 'La classificazione degli asset tiene conto dei requisiti normativi applicabili (NIS2, GDPR, ecc.)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 79, 'Esiste un processo per gestire e tracciare le licenze software per prevenire l''uso di software non autorizzato o vulnerabile?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'asset'), 80, 'La tua organizzazione ha un inventario delle informazioni e dei sistemi?', 'Priorità: ALTA'),
