  ((SELECT id FROM assessment_categories WHERE code = 'gov'), 93, 'La tua organizzazione ha definito i ruoli e le responsabilità per la sicurezza informatica internamente per il personale dipendente ed esternamente per le terze parti (ad esempio, fornitori, clienti e appaltatori)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'gov'), 94, 'Le politiche e le procedure adottate per garantire la sicurezza di reti e sistemi sono allineate ai principali standard di sicurezza informatica (ad esempio, ISO/IEC 27001, NIST)?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'gov'), 95, 'Le politiche e procedure pertinenti la sicurezza di reti e sistemi sono riviste e aggiornate periodicamente?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'gov'), 96, 'Esiste una persona o un team designato responsabile della supervisione delle politiche e delle pratiche di sicurezza informatica?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'gov'), 97, 'Gli organi direttivi sono consapevoli della loro potenziale responsabilità in caso di inosservanza degli adempimenti normativi previsti dalla NIS2?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'gov'), 98, 'I membri degli organi direttivi sono tenuti a sottoporsi a una formazione periodica sulla sicurezza informatica?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'gov'), 99, 'Esiste una documentazione attestante la partecipazione e il completamento dei programmi di formazione da parte di tutti i membri degli organi direttivi?', 'Priorità: MEDIA'),
  ((SELECT id FROM assessment_categories WHERE code = 'gov'), 100, 'Tutti gli utenti privilegiati nella tua organizzazione comprendono i propri ruoli e responsabilità?', 'Priorità: ALTA'),
  ((SELECT id FROM assessment_categories WHERE code = 'hr'), 101, 'La tua organizzazione fornisce formazione sulla sicurezza informatica al personale?', 'Priorità: ALTA'),
