  ((SELECT id FROM assessment_categories WHERE code = 'hr'), 105, 'I dipendenti vengono sottoposti a test periodici (ad esempio, simulazioni di phishing) per verificare la loro capacità di riconoscere le minacce informatiche?', 'Priorità: MEDIA'),
